export function refundTotal(rows) {
  if (!Array.isArray(rows)) return { count: 0, total: 0 };
  const seen = new Set();
  const selected = [];
  for (const r of rows) {
    if (seen.has(r.id)) continue;
    seen.add(r.id);
    if (r.approved === true) selected.push(r);
  }
  let total = 0;
  for (const r of selected) {
    if (typeof r.amount === 'number') total += r.amount;
  }
  return { count: selected.length, total };
}

// refunds.mjs
// refundTotal(rows) -> { count, total }
// 1) Deduplicate rows by `id`, keeping the first occurrence (in original order).
// 2) Among the deduplicated rows, keep only those with approved === true.
// 3) `count` = number of such rows; `total` = sum of their `amount` values.
// Empty / non-array input returns { count: 0, total: 0 }.
// The input array and its records are never mutated. No dependencies.

export function refundTotal(rows) {
  const result = { count: 0, total: 0 };

  if (!Array.isArray(rows)) {
    return result;
  }

  const seenIds = new Set();

  for (const row of rows) {
    if (row === null || typeof row !== "object") {
      continue;
    }

    const id = row.id;

    // Dedupe by id (SameValueZero), keep first occurrence only.
    if (seenIds.has(id)) {
      continue;
    }
    seenIds.add(id);

    // After dedupe, require approved === true (strict).
    if (row.approved !== true) {
      continue;
    }

    result.count += 1;

    const amount = Number(row.amount);
    if (Number.isFinite(amount)) {
      result.total += amount;
    }
  }

  return result;
}

export default refundTotal;

