function toNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

export function refundTotal(rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    return { count: 0, total: 0 };
  }

  // Dedupe by id, first occurrence wins.
  // (Set uses SameValueZero, so NaN ids dedupe correctly as well.)
  const seen = new Set();
  let count = 0;
  let total = 0;

  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    if (row === null || row === undefined) {
      continue;
    }

    const key = row.id;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);

    // Among unique records, select approved ones and accumulate.
    if (row.approved === true) {
      count += 1;
      total += toNumber(row.amount);
    }
  }

  return { count, total };
}

export default refundTotal;

/**
 * Aggregate refund statistics.
 *
 * @param {Array<{id: unknown, approved: boolean, amount: number}>} rows
 *   Input rows (not mutated).
 * @returns {{count: number, total: number}} Number of unique approved
 *   refunds and the sum of their amounts.
 */
export function refundTotal(rows) {
  if (!Array.isArray(rows)) {
    return { count: 0, total: 0 };
  }

  const seenIds = new Set();
  let count = 0;
  let total = 0;

  for (const row of rows) {
    if (row === null || typeof row !== 'object') {
      continue;
    }

    // Deduplicate by id, keeping only the first occurrence.
    if (seenIds.has(row.id)) {
      continue;
    }
    seenIds.add(row.id);

    if (row.approved === true) {
      count += 1;
      const amount = Number(row.amount);
      if (Number.isFinite(amount)) {
        total += amount;
      }
    }
  }

  return { count, total };
}

