// Exports refundTotal(rows) -> { count, total }
//  1. Deduplicate rows by `id`, keeping the first occurrence.
//  2. Keep only records where `approved === true`.
//  3. Sum their `amount` values.
// Empty input returns { count: 0, total: 0 }.
// The input array and its records are never modified. No dependencies.

export function refundTotal(rows) {
  const zero = { count: 0, total: 0 };
  if (!Array.isArray(rows)) return zero;

  const seen = new Set();
  let count = 0;
  let total = 0;

  for (const row of rows) {
    if (row === null || typeof row !== 'object') continue;

    // Dedupe by id, first occurrence wins (applied before the approved filter).
    const id = row.id;
    if (id !== undefined) {
      if (seen.has(id)) continue;
      seen.add(id);
    }

    if (row.approved !== true) continue;

    count += 1;
    const amount = Number(row.amount);
    total += Number.isFinite(amount) ? amount : 0;
  }

  return { count, total };
}
